var exifParser=require("../index"),buf=require("fs").readFileSync(process.argv[2]),parser=exifParser.create(buf).enableReturnTags(!1),result=parser.parse();if(result.hasThumbnail("image/jpeg")){var size=result.getThumbnailSize(),buffer=result.getThumbnailBuffer();require("fs").writeFileSync(process.argv[3],buffer),console.log("wrote thumbnail of size "+size.width+"x"+size.height+" to "+process.argv[3]+" ("+buffer.length+" bytes)"),process.exit(0)}else console.log("no jpeg thumbnail in this image"),process.exit(1);